\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── World Bank Institutional Color Theme ──
\definecolor{primary}{HTML}{1A365D}      % deep navy
\definecolor{secondary}{HTML}{2B6CB0}    % medium blue
\definecolor{accent}{HTML}{D69E2E}       % amber/gold
\definecolor{bgposter}{HTML}{F7FAFC}     % light gray-blue
\definecolor{redbg}{HTML}{FFF9F0}        % warm cream
\definecolor{bluebg}{HTML}{EBF4FF}       % cool blue tint
\definecolor{tealbg}{HTML}{E6FFFA}       % teal tint
\definecolor{goldbg}{HTML}{FFFBEB}       % amber tint
\definecolor{redtitlebg}{HTML}{FEEBC8}   % title bar tint
\definecolor{bluetitlebg}{HTML}{BEE3F8}
\definecolor{tealtitlebg}{HTML}{B2F5EA}
\definecolor{goltitlebg}{HTML}{FEFCBF}
\definecolor{textdark}{HTML}{1A202C}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{FEFCBF}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goltitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!20!white,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Global Economic Prospects}\\[10pt]
  {\fontsize{30}{36}\selectfont Resilience Amid Uncertainty}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{white!80} World Bank Group — January 2026}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary} 1.2B}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Youth entering working age}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 6 Decades}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Strongest recovery}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary} 300M}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Mission 300 electricity}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accent} 1.5B}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Health services target}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ RECOVERY OVERVIEW (Column 1, top) ══
\posterbox[tealcard, title={A Historic Recovery — But Uneven}
]{name=recovery, column=1, between=row6 and row10}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Global growth recovered faster than expected from 2020 recession
    \item Strongest recovery in six decades for overall economy
    \item \textbf{But:} Vulnerable EMDEs continue to lag significantly
    \item Gap between advanced and developing economies is widening
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}\textbf{Key tension:} Resilience is real, but unevenly distributed}}
}

% ══ RISKS TO OUTLOOK (Column 1, middle) ══
\posterbox[goldcard, title={Risks to the Outlook}
]{name=risks, column=1, between=row10 and row15}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Trade tensions:} Escalating tariffs disrupt supply chains, dampen investment
    \item \textbf{Financial volatility:} Deteriorating sentiment tightens financing for EMDEs
    \item \textbf{Inventory correction:} Front-loaded purchases now being drawn down
    \item \textbf{Climate shocks:} Extreme weather threatens output and infrastructure
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!22}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}\textbf{Policy relevance:} Trade tensions and tariff effects are the most immediate threat to global growth momentum}}
}

% ══ STRATEGIC PRIORITIES (Column 1, bottom) ══
\posterbox[bluecard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=1, between=row15 and row20}{
  \fontsize{28}{38}\selectfont
  \begin{tabular}{p{0.42\linewidth}|p{0.48\linewidth}}
    \rowcolor{primary!15}
    \textbf{Initiative} & \textbf{Target} \\
    \hline
    \textbf{Health Services} & 1.5 billion people \\
    \textbf{Mission 300} & 300M people in Sub-Saharan Africa \\
    \textbf{AgriConnect} & 300M farmers up value chain \\
    \textbf{Capital Support} & 80M women \& businesses \\
    \textbf{Water Forward} & 1B+ people; \$400M WBG \\
  \end{tabular}
  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{With 1.2B youth entering workforce, job creation is central to the mission}}
}

% ══ POLICY ACTIONS (Column 2, top) ══
\posterbox[bluecard, title={Policy Actions for Sustained Growth}
]{name=policy, column=2, between=row6 and row12}{
  \fontsize{28}{38}\selectfont
  \begin{tabular}{p{0.35\linewidth}|p{0.28\linewidth}|p{0.28\linewidth}}
    \rowcolor{secondary!15}
    \textbf{Area} & \textbf{Global} & \textbf{Domestic} \\
    \hline
    \textbf{Trade} & Multilateral environment & Diversify partners \\
    \textbf{Finance} & Ease EMDE constraints & Macro frameworks \\
    \textbf{Climate} & Risk mitigation & Resilient infra \\
    \textbf{Investment} & Catalyze private capital & Remove bottlenecks \\
    \textbf{Jobs} & Cross-border mobility & Skills development \\
  \end{tabular}
  \vspace{6pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{secondary}\textbf{Essential:} Global and domestic action to sustain recovery and foster inclusive job creation}}
}

% ══ RESEARCH THEMES (Column 2, bottom) ══
\posterbox[tealcard, title={Key Research Themes}
]{name=research, column=2, between=row12 and row20}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Fiscal Policy:} Rebuilding fiscal space, fiscal rules, small state challenges
    \item \textbf{Trade \& Supply Chains:} Trade costs, COVID-19 impact on GVCs
    \item \textbf{Commodity Markets:} Price cycles, Russia-Ukraine energy implications
    \item \textbf{Financial Spillovers:} Rising US rates, fourth wave of debt buildup
    \item \textbf{Pandemic Economics:} COVID-19 impact on income inequality
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont\color{primary}\textbf{Analytical depth} underpins policy recommendations and strategic priorities}}
}

\end{tcbposter}
\end{document}

