\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── World Bank Institutional Color Theme ──
\definecolor{primary}{HTML}{1A365D}      % deep navy
\definecolor{secondary}{HTML}{2B6CB0}    % medium blue
\definecolor{accent}{HTML}{D69E2E}       % amber/gold
\definecolor{bgposter}{HTML}{F7FAFC}     % light gray-blue
\definecolor{bluebg}{HTML}{EBF4FF}       % cool blue tint
\definecolor{tealbg}{HTML}{E6FFFA}       % teal tint
\definecolor{goldbg}{HTML}{FFFBEB}       % amber tint
\definecolor{redbg}{HTML}{FFF5F5}        % warm pink
\definecolor{bluetitlebg}{HTML}{BEE3F8}
\definecolor{tealtitlebg}{HTML}{B2F5EA}
\definecolor{goltitlebg}{HTML}{FEFCBF}
\definecolor{textdark}{HTML}{1A202C}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{FFFBEB}
\definecolor{stathighlight2}{HTML}{EBF8FF}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goltitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=12pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{78}{94}\selectfont\bfseries Global Economic Prospects}\\[12pt]
  {\fontsize{36}{44}\selectfont Resilience Amid Uncertainty}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{white!75} World Bank Group — January 2026 Report}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=5pt, bottom=5pt,
  valign=center, borderline south={4pt}{0pt}{primary!50},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \colorbox{primary!20}{\parbox{0.92\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{primary} 1.2B}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Youth entering working age}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{secondary} 6 Decades}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Strongest recovery}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \colorbox{primary!20}{\parbox{0.92\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{primary} 300M}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Mission 300 electricity}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \colorbox{accent!25}{\parbox{0.92\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{accent} 1.5B}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Health services target}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ RECOVERY OVERVIEW (Column 1, row 6-10) ══
\posterbox[tealcard, title={A Historic Recovery — But Uneven}
]{name=recovery, column=1, between=row6 and row10}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Global economy recovered faster than expected from 2020 recession
    \item \textbf{Strongest recovery in six decades} for the overall economy
    \item \textbf{But:} Vulnerable EMDEs continue to lag significantly
    \item Widening gap between advanced and developing economies
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{primary}\textbf{Key tension:} Resilience is real, but unevenly distributed}}
}

% ══ RISKS TO OUTLOOK (Column 1, row 10-15) ══
\posterbox[goldcard, title={Risks to the Outlook}
]{name=risks, column=1, between=row10 and row15}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Trade tensions:} Escalating tariffs disrupt supply chains and dampen investment
    \item \textbf{Financial volatility:} Deteriorating sentiment tightens financing for EMDEs
    \item \textbf{Inventory correction:} Front-loaded purchases now being drawn down
    \item \textbf{Climate shocks:} Extreme weather threatens output and infrastructure
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!25}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}\textbf{Policy focus:} Trade tensions and tariff effects pose the most immediate threat}}
}

% ══ STRATEGIC PRIORITIES (Column 1, row 15-20) ══
\posterbox[bluecard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=1, between=row15 and row20}{
  \fontsize{28}{38}\selectfont
  \begin{tabular}{p{0.40\linewidth}|p{0.50\linewidth}}
    \rowcolor{secondary!15}
    \textbf{Initiative} & \textbf{Target} \\
    \hline
    \textbf{Health Services} & 1.5 billion people covered \\
    \textbf{Mission 300} & 300M in Sub-Saharan Africa get electricity \\
    \textbf{AgriConnect} & 300M farmers move up value chain \\
    \textbf{Capital Support} & 80M women \& women-led businesses \\
    \textbf{Water Forward} & 1B+ people; \$400M WBG commitment \\
  \end{tabular}
  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{With 1.2B youth entering workforce, job creation is central to the mission}}
}

% ══ POLICY ACTIONS (Column 2, row 6-12) ══
\posterbox[bluecard, title={Policy Actions for Sustained Growth}
]{name=policy, column=2, between=row6 and row12}{
  \fontsize{28}{38}\selectfont
  \begin{tabular}{p{0.30\linewidth}|p{0.30\linewidth}|p{0.30\linewidth}}
    \rowcolor{secondary!15}
    \textbf{Area} & \textbf{Global} & \textbf{Domestic} \\
    \hline
    \textbf{Trade} & Improve multilateral environment & Diversify trade partners \\
    \textbf{Finance} & Ease EMDE financing constraints & Strengthen macro frameworks \\
    \textbf{Climate} & Scale up risk mitigation & Invest in resilient infrastructure \\
    \textbf{Investment} & Catalyze private capital flows & Remove structural bottlenecks \\
    \textbf{Jobs} & Support cross-border mobility & Enhance skills development \\
  \end{tabular}
  \vspace{6pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{secondary}\textbf{Essential:} Global and domestic action to sustain recovery and foster inclusive job creation}}
}

% ══ RESEARCH THEMES (Column 2, row 12-20) ══
\posterbox[tealcard, title={Key Research Themes}
]{name=research, column=2, between=row12 and row20}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item \textbf{Fiscal Policy:} Rebuilding fiscal space through fiscal rules; fiscal challenges in small states
    \item \textbf{Trade \& Supply Chains:} High trade costs — causes and remedies; COVID-19 impact on GVCs
    \item \textbf{Commodity Markets:} Price cycles — drivers and policies; Russia-Ukraine energy implications
    \item \textbf{Financial Spillovers:} Rising U.S. interest rates; fourth wave of rapid debt buildup
    \item \textbf{Pandemic Economics:} COVID-19 impact on global income inequality
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont\color{primary}\textbf{Analytical depth} underpins policy recommendations}}
}

\end{tcbposter}
\end{document}
